import { cacheTag } from 'next/cache';

export type Product = {
  sku: string;
  name: string;
  price: number;
  inventory: number;
  available: boolean;
};

// Simulates ERP/PIM data store. In production this would be a DB or external API.
let catalogStore: Product[] = [
  { sku: 'SKU-001', name: 'Widget A', price: 29.99, inventory: 150, available: true },
  { sku: 'SKU-002', name: 'Widget B', price: 49.99, inventory: 80, available: true },
  { sku: 'SKU-003', name: 'Widget C', price: 19.99, inventory: 0, available: false },
  { sku: 'SKU-004', name: 'Gadget X', price: 99.99, inventory: 25, available: true },
  { sku: 'SKU-005', name: 'Gadget Y', price: 149.99, inventory: 12, available: true },
];

export function getCatalogStore(): Product[] {
  return catalogStore;
}

export function setCatalogStore(products: Product[]): void {
  catalogStore = products;
}

export async function getProducts(): Promise<Product[]> {
  'use cache';
  cacheTag('products');
  const store = getCatalogStore();
  return [...store];
}

