import { revalidateTag } from 'next/cache';
import {
  getCatalogStore,
  setCatalogStore,
  type Product,
} from './products';

/**
 * Simulates syncing from upstream ERP/PIM. Runs in background.
 * When complete, updates the catalog store and revalidates the "products" cache tag
 * so subsequent requests get fresh data (stale-while-revalidate).
 */
export async function runCatalogSync(): Promise<void> {
  // Simulate fetching from ERP/PIM (in production: API calls, DB writes)
  await new Promise((resolve) => setTimeout(resolve, 2000));

  const current = getCatalogStore();
  const synced: Product[] = current.map((p) => ({
    ...p,
    // Simulate upstream data changes (e.g. price/inventory updates)
    price: Math.round(p.price * (0.98 + Math.random() * 0.06) * 100) / 100,
    inventory: Math.max(0, p.inventory + Math.floor((Math.random() - 0.3) * 20)),
    available: p.inventory > 0,
  }));

  setCatalogStore(synced);

  // Mark "products" cache as stale; next visit uses stale-while-revalidate
  revalidateTag('products', 'max');
}

